from typing import List, Literal
from pydantic import BaseModel, Field

from app.models.enums import IncidentCategory, IncidentPriority

# "AI" = answer generated by the local Ollama model; "RULE_BASED" = keyword/template fallback
AISource = Literal["AI", "RULE_BASED"]


class TriageSuggestionRequest(BaseModel):
    title: str = Field(..., min_length=1, max_length=150)
    description: str = Field(..., min_length=1, max_length=5000)


class TriageSuggestionResponse(BaseModel):
    category: IncidentCategory
    priority: IncidentPriority
    reasoning: str
    source: AISource


class IncidentSummaryResponse(BaseModel):
    incident_id: int
    ticket_code: str
    summary: str
    source: AISource


class TroubleshootingResponse(BaseModel):
    incident_id: int
    ticket_code: str
    steps: List[str]
    reference_tickets: List[str]
    source: AISource
